window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["observability"]={"title":"可观测性与追踪：重建一次 AI 请求为何得到这个结果","subtitle":"用 trace、span、版本、质量信号和最小化数据，把“偶发答错”变成可定位、可回放、可回归的问题。","thesis":"AI 可观测性不是把所有 prompt 永久存下来，而是让团队仅凭系统产生的证据就能提出并检验故障假设：一次用户任务的输入摘要、检索、模型、工具、重试、版本和最终结果必须串成因果时间线，同时满足<b>隐私最小化、采样代表性和可执行响应</b>。","quality":{"contractVersion":2,"examples":[{"section":5,"evidence":{"setup":"1.42 秒到底慢在哪里","rule":"根时长只由关键路径决定","steps":"1420ms 的主因是工具重试","interpretation":"所有 span 时长之和是工作量，不等于端到端时间"}}],"formulas":[{"id":"observability-critical-path","section":5,"formulaIndex":1,"symbols":[{"name":"Tcritical","meaning":"根 trace 的关键路径墙钟时间","evidence":"输出关键路径墙钟延迟 Tcritical"},{"name":"CriticalPath","meaning":"考虑依赖与并行关系的最长完成路径函数","evidence":"并行阶段取决定完成的最长依赖路径"},{"name":"Tqueue","meaning":"关键路径上的排队时间","evidence":"排队计算网络和重试耗时"},{"name":"Tcompute","meaning":"关键路径上的模型与组件计算时间","evidence":"排队计算网络和重试耗时"},{"name":"Tnetwork","meaning":"关键路径上的网络时间","evidence":"排队计算网络和重试耗时"},{"name":"Tretry","meaning":"关键路径上的退避和重试时间","evidence":"工具重试"}]},{"id":"observability-weighted-rate","section":7,"formulaIndex":1,"symbols":[{"name":"RateWeighted","meaning":"修正不等概率采样后的总体率估计","evidence":"输出 HorvitzThompson 风格加权率 RateWeighted"},{"name":"i","meaning":"被观测请求编号","evidence":"每条 trace"},{"name":"yi","meaning":"第 i 条请求的目标结果指示或数值","evidence":"结果 yi"},{"name":"pii","meaning":"第 i 条请求被保留的概率","evidence":"保留概率 pii"}]}],"termReviews":[{"section":3,"reviewedAt":"2026-07-27","terms":[{"name":"trace","meaning":"对应一次用户任务的跨组件完整因果轨迹","purpose":"把一次请求的检索模型工具与结果串成时间线","definitionEvidence":"输出一个根 trace","purposeEvidence":"context 跨边界传播"},{"name":"span","meaning":"trace 内一次有明确开始结束和父级的操作","purpose":"记录单个组件调用的时间版本状态与副作用","definitionEvidence":"有父子关系的 span 树","purposeEvidence":"每个 span 记录时间、父级、版本、状态和实际副作用"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"AI 可观测性重建请求从输入到副作用的版本化因果时间线。","evidence":"HTTP 200 为什么仍可能是严重失败"},"problem":{"answer":"它发现传输成功但语义证据权限或业务动作失败。","evidence":"退款助手怎样依然伤害用户"},"inputOutput":{"answer":"输入链路事件，输出可定位回放验证的因果时间线。","evidence":"输出可定位、回放和验证的因果时间线"},"mechanism":{"answer":"串联实际收到的输入、调用、观察和最终状态。","evidence":"trace 记录实际输入动作和状态"},"interpretation":{"answer":"HTTP 成功只说明传输完成，不说明 AI 任务成功。","evidence":"不表示语义、证据、权限或业务动作正确"},"boundary":{"answer":"观测不要求默认永久保存全部敏感原文。","evidence":"敏感原文并非默认必存"}},{"section":2,"definition":{"answer":"日志、指标、追踪和评测标签是互补观测信号。","evidence":"日志、指标和追踪各回答不同问题"},"problem":{"answer":"它解释已有海量日志为何事故时仍无法判断规模和链路。","evidence":"为什么事故发生时仍然只能猜"},"inputOutput":{"answer":"输入事件趋势路径和判断，输出对应信号类别。","evidence":"输出 log、metric、trace 或评测标签"},"mechanism":{"answer":"用 trace ID 和版本把四层信号相互连接。","evidence":"四者通过 trace ID 和版本连接"},"interpretation":{"answer":"日志解释步骤，指标看趋势，trace 看路径，标签看质量。","evidence":"日志解释某步发生什么"},"boundary":{"answer":"缺少任一层级都会留下特定诊断盲区。","evidence":"只有其中一种都会留下诊断盲区"}},{"section":3,"definition":{"answer":"根 trace 表示用户任务，span 表示其中有边界的操作。","evidence":"Trace 和 span 怎样表达一次任务"},"problem":{"answer":"它把十次模型工具调用保持在同一因果链中。","evidence":"怎样保持同一条因果链"},"inputOutput":{"answer":"输入跨组件调用，输出根 trace 和父子 span 树。","evidence":"输出一个根 trace 与有父子关系的 span 树"},"mechanism":{"answer":"传播 context 并记录每个 span 的时间父级版本状态。","evidence":"context 跨边界传播"},"interpretation":{"answer":"工具 span 和业务状态才是调用及副作用证据。","evidence":"工具 span 与业务状态才是调用证据"},"boundary":{"answer":"模型事后叙述不能替代系统实际记录。","evidence":"不能替代系统记录"}},{"section":4,"definition":{"answer":"复现字段保存足以比较发布前后差异的版本证据。","evidence":"记录足以复现的版本，而不是一团文本"},"problem":{"answer":"它定位同样输入昨天成功今天失败时哪些条件改变。","evidence":"最少需要比较哪些变化"},"inputOutput":{"answer":"输入版本和调用字段，输出最小证据与受控引用。","evidence":"输出最小可比较的版本证据与受控内容引用"},"mechanism":{"answer":"以哈希稳定 ID 和版本连接模型提示索引工具策略。","evidence":"哈希和稳定 ID 支持差异定位"},"interpretation":{"answer":"记录过少不能复现，记录全部会扩大隐私风险。","evidence":"记录太少无法复现，记录全部又扩大隐私面"},"boundary":{"answer":"自由思维链不应作为系统事实或调用证据。","evidence":"自由思维链不作为事实证据"}},{"section":5,"definition":{"answer":"端到端延迟由依赖图中的关键路径墙钟时间决定。","evidence":"运行示例：1.42 秒到底慢在哪里"},"problem":{"answer":"它回答根 trace 时长是否等于所有 span 时长相加。","evidence":"等于所有 span 时长相加吗"},"inputOutput":{"answer":"输入 span 时间依赖与阶段耗时，输出关键路径延迟。","evidence":"输出关键路径墙钟延迟 Tcritical"},"mechanism":{"answer":"串行相加，并行只计决定最终完成的最长依赖路径。","evidence":"并行阶段取决定完成的最长依赖路径"},"interpretation":{"answer":"全部 span 时长之和表示工作量，不是墙钟完成时间。","evidence":"不等于端到端时间"},"boundary":{"answer":"本例主因是工具重试，不能归咎于模型平均耗时。","evidence":"主因是工具重试"}},{"section":6,"definition":{"answer":"语义监控把质量标签异步回写到具体 trace 和版本切片。","evidence":"质量指标必须连接到具体 trace 和切片"},"problem":{"answer":"它定位点赞下降来自哪些任务版本和失败类型。","evidence":"怎样知道是哪些任务、哪个版本和哪类失败"},"inputOutput":{"answer":"输入质量标签，输出分任务版本群体的趋势。","evidence":"输出按任务语言风险模型提示索引和群体切片的质量趋势"},"mechanism":{"answer":"聚合趋势后下钻到脱敏 trace 和实际路径验证。","evidence":"必须下钻到脱敏 trace"},"interpretation":{"answer":"点赞转人工重问等在线代理不等于真实质量。","evidence":"代理指标只提供根因线索"},"boundary":{"answer":"代理信号必须用人工或最终业务状态校验。","evidence":"必须下钻到脱敏 trace，并用人工或最终业务状态校验"}},{"section":7,"definition":{"answer":"不等概率 trace 采样可用纳入概率加权估计总体率。","evidence":"采样、基数与成本怎样不破坏证据"},"problem":{"answer":"它解决千万流量不能全存又不能漏掉事故的问题。","evidence":"只随机 1% 又会漏掉事故吗"},"inputOutput":{"answer":"输入结果和保留概率，输出修正后的加权率。","evidence":"输出 HorvitzThompson 风格加权率 RateWeighted"},"mechanism":{"answer":"用结果除纳入概率加总，再除权重总和。","evidence":"分子求 Σ(yi/pii)"},"interpretation":{"answer":"高风险尾部可多采，但估总体时必须修正概率。","evidence":"必须记录纳入概率"},"boundary":{"answer":"只保存失败不能估总体失败率，灾难另走安全通道。","evidence":"不能直接估生产失败率"}},{"section":8,"definition":{"answer":"观测隐私治理按诊断目的最小化采集和访问敏感数据。","evidence":"隐私最小化和调试能力如何共存"},"problem":{"answer":"它解释全量 prompt 最好调试为何仍不可默认接受。","evidence":"为什么这不是默认可接受方案"},"inputOutput":{"answer":"输入目的敏感等级和保留，输出采集脱敏隔离决定。","evidence":"输出脱敏、哈希、加密原文隔离或不采集决定"},"mechanism":{"answer":"优先存类型范围代号，原文进入短期授权受控区。","evidence":"使用短期授权受控存储"},"interpretation":{"answer":"最小字段仍应保留足以诊断金额等错误的结构。","evidence":"能用类型范围和稳定代号诊断"},"boundary":{"answer":"删除必须传播到派生索引和备用日志。","evidence":"必须覆盖派生索引和备用日志"}},{"section":9,"definition":{"answer":"可观测闭环把告警连接到止损回滚根因验证和评测回流。","evidence":"告警、回滚和失败回流才构成闭环"},"problem":{"answer":"它防止仪表盘变红却没有负责人和处置动作。","evidence":"仪表盘变红但没人行动，能叫可观测吗"},"inputOutput":{"answer":"输入 SLO 告警和版本，输出止损回滚实验与样本。","evidence":"输出止损、回滚、根因实验与经审核的回归样本"},"mechanism":{"answer":"先恢复安全服务，再用 trace 和发布标记验证根因。","evidence":"先恢复安全服务，再研究长期修复"},"interpretation":{"answer":"处置与长期修复是两个步骤，不能为研究延迟止损。","evidence":"告警先恢复安全服务"},"boundary":{"answer":"可观测性不替代权限幂等和事故响应演练。","evidence":"不能替代权限、幂等和事故演练"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>设计 AI trace/span 结构；区分日志、指标和追踪；从延迟与质量信号定位故障；建立脱敏、采样、告警与回滚闭环。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>HTTP 200 为什么仍可能是严重失败<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">接口成功返回、没有异常栈，退款助手怎样依然伤害用户？</p><p>它可能检索到旧政策、把订单号传错给工具、重试后重复创建退款，或流畅地承诺无权限动作。传统日志擅长记录机器异常；LLM 系统还需要记录语义失败、证据路径和动作结果。</p><p>可观测性不是“看见模型脑内真实思考”。它重建模型实际收到的版本化输入、实际调用、外部观察和最终副作用，让工程师区分：输入问题、检索问题、生成问题、工具问题、策略问题或环境变化。</p><div class=\"dd-note\"><b>核心测试：</b>值班人员在不复现用户敏感原文的前提下，能否从 trace 回答“哪一步、用哪个版本、基于什么证据、产生了什么状态变化”？</div><p>AI 可观测性输入版本化请求、检索、模型、工具、策略和副作用事件，输出可定位、回放和验证的因果时间线。HTTP 200 只表示传输成功，不表示语义、证据、权限或业务动作正确；trace 记录实际输入动作和状态，不声称读取模型真实思维。敏感原文并非默认必存。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>日志、指标和追踪各回答不同问题<span class=\"dd-badge intuition\">消歧</span></h2><p class=\"dd-lead\">已经有海量日志，为什么事故发生时仍然只能猜？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>信号</th><th>结构</th><th>最擅长回答</th><th>退款助手例子</th></tr></thead><tbody><tr><td>日志 log</td><td>离散事件</td><td>某一步发生了什么</td><td>工具返回 permission_denied</td></tr><tr><td>指标 metric</td><td>聚合时间序列</td><td>规模和趋势是否异常</td><td>p95 延迟、越权拦截率</td></tr><tr><td>追踪 trace</td><td>有父子的 span</td><td>一次请求如何跨组件流动</td><td>检索→模型→工具→重试</td></tr><tr><td>评测标签</td><td>样本级判断</td><td>结果好不好及失败类型</td><td>资格错、引用不支持</td></tr></tbody></table></div><p>指标发现“错误承诺率上升”，trace 找到受影响请求和版本，日志解释具体返回，评测标签确认语义失败。缺一个层级都可能出现盲区：只有 trace 不知问题是否普遍，只有指标不知如何复现。</p><p>信号分类输入离散事件、聚合趋势、跨组件路径和样本质量判断，输出 log、metric、trace 或评测标签。日志解释某步发生什么，指标发现规模趋势，trace 串联一次请求，标签判断结果好坏；四者通过 trace ID 和版本连接。只有其中一种都会留下诊断盲区。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>Trace 和 span 怎样表达一次任务<span class=\"dd-badge eng\">机制</span></h2><p class=\"dd-lead\">一次用户提问触发十次模型与工具调用，怎样保持同一条因果链？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 720 270\" role=\"img\" aria-label=\"退款助手 trace 中检索、模型、工具和重试 span 的父子关系\"><defs><marker id=\"ob1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"18\" y=\"24\" width=\"684\" height=\"52\" rx=\"9\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"36\" y=\"48\" class=\"svg-t\">trace 9f2：用户任务（总 1.42 s）</text><text x=\"36\" y=\"66\" class=\"svg-t\" font-size=\"11\">session=u_7 的哈希 · app=v42 · policy=2026-07-18</text><rect x=\"62\" y=\"106\" width=\"130\" height=\"54\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"127\" y=\"129\" text-anchor=\"middle\" class=\"svg-t\">retrieval 180 ms</text><text x=\"127\" y=\"148\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">index=p17 · top5</text><rect x=\"226\" y=\"106\" width=\"130\" height=\"54\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"291\" y=\"129\" text-anchor=\"middle\" class=\"svg-t\">model 620 ms</text><text x=\"291\" y=\"148\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">prompt=h83 · 418 tok</text><rect x=\"390\" y=\"106\" width=\"130\" height=\"54\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"455\" y=\"129\" text-anchor=\"middle\" class=\"svg-t\">refund tool 90 ms</text><text x=\"455\" y=\"148\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">attempt=1 · timeout</text><rect x=\"554\" y=\"106\" width=\"130\" height=\"54\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"619\" y=\"129\" text-anchor=\"middle\" class=\"svg-t\">retry 310 ms</text><text x=\"619\" y=\"148\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">same idempotency key</text><path d=\"M127,76 L127,104\" stroke=\"#6b7484\" marker-end=\"url(#ob1)\"/><path d=\"M291,76 L291,104\" stroke=\"#6b7484\" marker-end=\"url(#ob1)\"/><path d=\"M455,76 L455,104\" stroke=\"#6b7484\" marker-end=\"url(#ob1)\"/><path d=\"M619,76 L619,104\" stroke=\"#6b7484\" marker-end=\"url(#ob1)\"/><path d=\"M192,133 L224,133\" stroke=\"#6b7484\" marker-end=\"url(#ob1)\"/><path d=\"M356,133 L388,133\" stroke=\"#6b7484\" marker-end=\"url(#ob1)\"/><path d=\"M520,133 L552,133\" stroke=\"#6b7484\" marker-end=\"url(#ob1)\"/><rect x=\"226\" y=\"195\" width=\"294\" height=\"48\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"373\" y=\"216\" text-anchor=\"middle\" class=\"svg-t\">最终状态：created_once · judge=policy_pass</text><text x=\"373\" y=\"234\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">实际轨迹证明重试，没有依赖模型事后解释</text><path d=\"M619,160 C617,215 544,219 522,219\" fill=\"none\" stroke=\"#6b7484\" marker-end=\"url(#ob1)\"/></svg><figcaption>图 1　根 trace 对应用户任务，span 对应有边界的操作；父子关系、事件时间和幂等键让重复与副作用可诊断。</figcaption></figure><p>trace context 必须跨 HTTP、队列和后台任务传播；每个 span 记录开始/结束、父 span、状态与属性。模型生成的“我调用了一次工具”不是证据，工具 span 和业务数据库状态才是。</p><p>追踪结构输入用户任务和跨 HTTP、队列、后台任务的调用，输出一个根 trace 与有父子关系的 span 树。每个 span 记录时间、父级、版本、状态和实际副作用，context 跨边界传播；工具 span 与业务状态才是调用证据。模型事后声称做过什么不能替代系统记录。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>记录足以复现的版本，而不是一团文本<span class=\"dd-badge eng\">字段</span></h2><p class=\"dd-lead\">同样的输入昨天成功今天失败，最少需要比较哪些变化？</p><p>记录应用发布号、模型供应商/快照、系统提示哈希、模板变量 schema、采样参数、检索查询、索引/嵌入/重排版本、候选文档 ID、工具 schema/响应状态、策略规则、token、费用和最终验收。可保存内容哈希或受控引用，避免把原始敏感文本复制到每个日志系统。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>字段族</th><th>示例</th><th>诊断价值</th></tr></thead><tbody><tr><td>关联</td><td>trace/span/session/request id</td><td>跨组件串联和去重</td></tr><tr><td>版本</td><td>app v42、prompt h83、index p17</td><td>比较发布前后与回滚</td></tr><tr><td>输入证据</td><td>脱敏意图、文档 ID/跨度</td><td>重建模型可见信息</td></tr><tr><td>行为</td><td>工具名、参数摘要、幂等键</td><td>审计副作用</td></tr><tr><td>结果</td><td>验收、人工改判、成熟标签</td><td>连接质量而非只看状态码</td></tr></tbody></table></div><div class=\"dd-note warn\"><b>不要记录自由思维链作为真相。</b>　它可能不忠实、含敏感数据且成本高。保存简洁决策摘要与实际可观测动作即可。</div><p>复现字段输入应用、模型、提示、参数、索引、候选、工具、策略和验收版本，输出最小可比较的版本证据与受控内容引用。哈希和稳定 ID 支持差异定位，同时避免原文复制到每个日志系统；记录太少无法复现，记录全部又扩大隐私面。自由思维链不作为事实证据。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>运行示例：1.42 秒到底慢在哪里<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">根 trace 时长等于所有 span 时长相加吗？</p><p>图中检索 180ms、模型 620ms、工具 90ms、退避与重试 310ms，另有编排 220ms；若全串行，总和就是 1420ms。若检索与安全分类并行，两个 span 重叠，根时长只由关键路径决定，不能把所有子 span 相加当端到端延迟。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"关键路径端到端延迟\"><mi>Tcritical</mi><mo>=</mo><mi>CriticalPath</mi><mo>(</mo><mi>Tqueue</mi><mo>,</mo><mi>Tcompute</mi><mo>,</mo><mi>Tnetwork</mi><mo>,</mo><mi>Tretry</mi><mo>)</mo></math></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>阶段</th><th>本次</th><th>过去 p95</th><th>判断</th></tr></thead><tbody><tr><td>检索</td><td>180ms</td><td>210ms</td><td>正常</td></tr><tr><td>模型首 token</td><td>410ms</td><td>390ms</td><td>略慢</td></tr><tr><td>完整生成</td><td>620ms</td><td>760ms</td><td>正常</td></tr><tr><td>工具+重试</td><td>400ms</td><td>110ms</td><td>异常主因</td></tr><tr><td>总时长</td><td>1420ms</td><td>1180ms</td><td>超 SLO</td></tr></tbody></table></div><p>只看平均总延迟会把工具超时归咎于模型。还要拆 TTFT、每 token 时间、检索、工具、排队和重试，并观察 p50/p95/p99；长尾用户体验不会由平均数代表。</p><p>延迟案例输入 span 开始结束、依赖关系、排队计算网络和重试耗时，输出关键路径墙钟延迟 Tcritical。串行阶段相加，并行阶段取决定完成的最长依赖路径；所有 span 时长之和是工作量，不等于端到端时间。1420ms 的主因是工具重试，而不是模型平均生成。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>质量指标必须连接到具体 trace 和切片<span class=\"dd-badge eng\">语义监控</span></h2><p class=\"dd-lead\">点赞率下降后，怎样知道是哪些任务、哪个版本和哪类失败？</p><p>把离线评分器或延迟人工标签异步回写到 trace：资格正确、引用支持、越权、工具完成、人工改判。聚合时按任务、语言、风险、模型、提示、索引和客户群切片；仪表盘上的点应能下钻到已脱敏样本和实际路径。</p><p>在线代理指标如拒答率、转人工、用户重问、工具撤销和引用点击响应快，但并非真值。满意度可能偏爱自信过度承诺；转人工下降也可能是升级规则坏了。每个代理需写可能的替代解释，并用抽样人工或最终业务状态校验。</p><div class=\"dd-note\"><b>从指标到假设：</b>“引用失败率从 2% 到 7%”只是信号；下钻显示全部来自 index p17 且 retrieval span 没有文档，才形成可检验的根因候选。</div><p>语义监控输入异步回写的资格、引用、越权、工具完成和人工改判标签，输出按任务语言风险模型提示索引和群体切片的质量趋势。代理指标只提供根因线索，点赞、转人工和重问都可能有替代解释；必须下钻到脱敏 trace，并用人工或最终业务状态校验。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>采样、基数与成本怎样不破坏证据<span class=\"dd-badge math\">采样</span></h2><p class=\"dd-lead\">流量每天一千万条，不可能全量保存；只随机 1% 又会漏掉事故吗？</p><p>可对常规成功 trace 低比例头部采样，对错误、高风险、极慢和新版本提高尾部采样；但尾部规则要在 trace 完成后决定，并保留纳入概率，估总体率时才能加权。若只保存失败，就不能用样本中失败占比估生产失败率。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"按采样纳入概率加权的率估计\"><mi>RateWeighted</mi><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>i</mi></munder><mfrac><mi>yi</mi><mi>pii</mi></mfrac></mrow><mrow><munder><mo>∑</mo><mi>i</mi></munder><mfrac><mn>1</mn><mi>pii</mi></mfrac></mrow></mfrac></math></div><p>指标标签不能直接放用户 ID、完整 prompt 或文档 ID，否则高基数会炸毁时序系统并泄露信息。高基数字段留在受控 trace 存储，指标只用有限枚举切片。对极低频灾难还要使用专门安全事件通道，不依赖普通采样。</p><div class=\"dd-note warn\"><b>采样偏差：</b>仅抽“用户点踩”的请求会漏掉用户没意识到的错误，尤其是流畅幻觉；应加入随机审计。</div><p>采样估计输入每条 trace 的结果 yi 和保留概率 pii，输出 HorvitzThompson 风格加权率 RateWeighted。分子求 Σ(yi/pii)，分母求 Σ(1/pii)；尾部采样可多保错误和高风险，但必须记录纳入概率。只保存失败样本不能直接估生产失败率，极低频灾难另走安全事件通道。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>隐私最小化和调试能力如何共存<span class=\"dd-badge eng\">治理</span></h2><p class=\"dd-lead\">全量 prompt 最好调试，为什么这不是默认可接受方案？</p><p>prompt、附件和工具参数可能含 PII、健康信息、商业秘密和凭证；复制到日志会扩大访问者、区域、保留期和泄漏面。先按目的定义必要字段：能用订单哈希和错误码复现，就不存姓名与原文；需要内容审查时，将加密原文置于独立受控存储，以短期授权访问。</p><ol class=\"dd-steps\"><li>采集前分类字段，默认关闭原文与密钥。</li><li>入口结构化脱敏，避免正则事后清洗遗漏嵌套工具参数。</li><li>按角色限制访问并记录每次查看；生产与开发隔离。</li><li>定义保留、删除、地域和用户请求流程；删除要覆盖派生索引。</li><li>测试 trace 管道本身不会因异常把未脱敏 payload 打入备用日志。</li></ol><p>过度脱敏也会损坏证据，如把所有数字抹掉后无法诊断金额错误。应保存类型、范围或稳定代号，让诊断需求和隐私风险逐字段权衡。</p><p>隐私治理输入每个观测字段的诊断目的、敏感等级、访问者、地域和保留期，输出脱敏、哈希、加密原文隔离或不采集决定。能用类型范围和稳定代号诊断就不复制姓名凭证；需要内容审查时使用短期授权受控存储。删除必须覆盖派生索引和备用日志。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>告警、回滚和失败回流才构成闭环<span class=\"dd-badge intuition\">运维</span></h2><p class=\"dd-lead\">仪表盘变红但没人行动，能叫可观测吗？</p><p>每个告警应绑定服务目标、阈值、持续窗口、负责人、诊断查询、处置和回滚版本。用 burn-rate 告警区分偶发噪声与正在快速耗尽错误预算的事件；发布标记必须出现在时间线上。</p><p>退款越权率越线时，先冻结自动工具或切回旧策略，再检查受影响 trace 是否集中于 prompt h83、policy 版本或某语言。确认根因后构造最小回归样本，加入评测候选池，经审核进入下一版冻结集。恢复服务与修复模型是两个步骤，不能为了研究原因延迟止损。</p><div class=\"dd-note warn\"><b>失败边界：</b>可观测性只能发现被记录、被定义和被查看的问题；它不能替代权限隔离、幂等、评测或事故响应演练。</div><p>响应闭环输入 SLO、错误预算、告警窗口、负责人、诊断查询和回滚版本，输出止损、回滚、根因实验与经审核的回归样本。告警先恢复安全服务，再研究长期修复；发布标记和受影响 trace 用于验证假设。可观测性不能替代权限、幂等和事故演练。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">收集数据不是目的；缩短从异常到可靠处置的时间才是。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>日志越多越可观测</td><td>需关联、版本、语义标签和可执行响应</td></tr><tr><td>trace 就是思维链</td><td>trace 记录实际组件与动作，不宣称读取内部推理</td></tr><tr><td>全量保存最可靠</td><td>会扩大隐私、成本和高基数风险</td></tr><tr><td>用户点赞代表正确</td><td>它是有选择偏差的代理，需真值抽查</td></tr><tr><td>看见相关版本就是根因</td><td>需消融、回放或回滚对照检验假设</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>分布式追踪、日志、指标、LLM 应用结构</td></tr><tr><td><b>本页核心</b></td><td>trace/span、版本证据、语义指标、采样、隐私、告警</td></tr><tr><td>质量闭环</td><td>应用评测、模型评测、不确定性校准</td></tr><tr><td>生产治理</td><td>数据漂移、部署、人在回路、工作流幂等与事故响应</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>为用户任务生成并传播 trace context</li><li>组件 span 记录版本/证据/动作</li><li>质量与系统指标按切片聚合</li><li>异常下钻到受控 trace 提出假设</li><li>回滚/消融验证并止损</li><li>审核失败样本并回流评测</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>HTTP 200 为什么不能代表 AI 任务成功？</li><li>根 trace 时长为何不能总由子 span 相加？</li><li>为什么只采失败样本不能估失败率？</li><li>哪些版本最值得记录？</li><li>可观测闭环的最后一步是什么？</li><li>假设“可观测性与追踪：重建一次 AI 请求为何得到这个结果”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>传输成功时语义、证据、权限、工具副作用仍可失败。</li><li>并行 span 会重叠，端到端由关键路径决定。</li><li>纳入概率依赖结果，样本分布不代表总体；需概率和加权。</li><li>应用、模型、提示、索引/重排、工具 schema、策略和数据版本。</li><li>先处置/回滚，再将经审核的失败转成回归评测并验证修复。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://opentelemetry.io/docs/specs/otel/\" target=\"_blank\" rel=\"noopener\">OpenTelemetry Specification</a>：trace、metric、log 与 context 语义</li><li><a href=\"https://papers.nips.cc/paper/5656-hidden-technical-debt-in-machine-learning-systems\" target=\"_blank\" rel=\"noopener\">Hidden Technical Debt in Machine Learning Systems</a>：ML 系统依赖、反馈和监控债务</li><li><a href=\"https://sre.google/workbook/alerting-on-slos/\" target=\"_blank\" rel=\"noopener\">Google SRE Workbook: Alerting on SLOs</a>：错误预算与多窗口告警</li><li><a href=\"https://www.nist.gov/privacy-framework\" target=\"_blank\" rel=\"noopener\">NIST Privacy Framework</a>：数据处理与隐私风险治理</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
